/* 학습 해설
 * EROFS·읽기 전용과 압축 Cluster
 * 배포 이미지처럼 변하지 않는 파일을 작게 저장하면서 임의 위치를 읽으려면 압축 단위와 메타데이터 위치를 연결해야 합니다.
 * EROFS는 읽기 전용 파일시스템입니다. 압축된 physical cluster와 파일의 logical cluster 관계를 메타데이터로 찾고 필요한 범위를 해제합니다. 모든 파일이 항상 압축되는 것은 아니며 지원 layout·feature·block 크기를 superblock에서 검사합니다.
 * 지원 mkfs.erofs로 만든 별도 이미지의 읽기 경로를 관찰합니다. 읽기 전용 특성·압축 방식·cache·DAX 지원 조건을 구분하고 이미지를 일반 수정 가능한 디스크로 취급하지 않습니다.
 */
static int erofs_read_superblock(struct super_block *sb)
{
	struct erofs_sb_info *sbi = EROFS_SB(sb);
	struct erofs_buf buf = __EROFS_BUF_INITIALIZER;
	struct erofs_super_block *dsb;
	void *data;
	int ret;

	data = erofs_read_metabuf(&buf, sb, 0, EROFS_KMAP);
	if (IS_ERR(data)) {
		erofs_err(sb, "cannot read erofs superblock");
		return PTR_ERR(data);
	}

	dsb = (struct erofs_super_block *)(data + EROFS_SUPER_OFFSET);
	ret = -EINVAL;
	if (le32_to_cpu(dsb->magic) != EROFS_SUPER_MAGIC_V1) {
		erofs_err(sb, "cannot find valid erofs superblock");
		goto out;
	}

	sbi->blkszbits  = dsb->blkszbits;
	if (sbi->blkszbits < 9 || sbi->blkszbits > PAGE_SHIFT) {
		erofs_err(sb, "blkszbits %u isn't supported", sbi->blkszbits);
		goto out;
	}

