/* 학습 해설
 * Ceph·분산 객체와 Metadata Server
 * 여러 서버에 파일 내용을 나눠 저장할 때 파일 이름·권한과 실제 데이터 위치를 서로 다른 서비스가 관리할 수 있습니다.
 * CephFS client는 MDS를 통해 namespace와 metadata·capability를 다루고 OSD 경로로 파일 데이터를 접근합니다. Capability는 client가 어떤 cache·수정을 할 수 있는지 조정합니다. 네트워크 지연·재연결·서버 장애가 로컬 디스크와 다른 비용을 만듭니다.
 * 학습용 Ceph cluster의 mount·client cache·cap·sync를 관찰합니다. 인증·pool·MDS·OSD 상태와 지원 설정을 확인하고 데이터 IO 성공을 모든 metadata의 영속 완료로 간주하지 않습니다.
 */
static int ceph_sync_fs(struct super_block *sb, int wait)
{
	struct ceph_fs_client *fsc = ceph_sb_to_fs_client(sb);
	struct ceph_client *cl = fsc->client;

	if (!wait) {
		doutc(cl, "(non-blocking)\n");
		ceph_flush_dirty_caps(fsc->mdsc);
		ceph_flush_cap_releases(fsc->mdsc);
		doutc(cl, "(non-blocking) done\n");
		return 0;
	}

	doutc(cl, "(blocking)\n");
	ceph_osdc_sync(&fsc->client->osdc);
	ceph_mdsc_sync(fsc->mdsc);
	doutc(cl, "(blocking) done\n");
	return 0;
}

