/* 학습 해설
 * GFS2·분산 Lock과 Cluster Filesystem
 * 여러 노드가 같은 디스크를 수정할 때 각 CPU의 mutex만으로는 다른 노드의 cache와 쓰기를 조정할 수 없습니다.
 * GFS2는 glock으로 inode 등 자원의 cluster 접근 상태와 local holder queue를 연결합니다. 분산 lock 상태 전환과 local grant·demote·cache 정리가 협력합니다. 노드별 journal과 recovery·fencing이 장애 후 공유 저장소를 안전하게 다루는 데 필요합니다.
 * 격리된 cluster 실습에서 glock state·holder·DLM·journal을 관찰합니다. 정상 공유 디스크와 cluster 설정을 확인하고 단일 노드 spinlock을 분산 lock의 대체로 사용하지 않습니다.
 */
int gfs2_glock_nq(struct gfs2_holder *gh)
{
	struct gfs2_glock *gl = gh->gh_gl;
	int error;

	if (glock_blocked_by_withdraw(gl) && !(gh->gh_flags & LM_FLAG_NOEXP))
		return -EIO;

	if (gh->gh_flags & GL_NOBLOCK) {
		struct gfs2_holder *current_gh;

		error = -ECHILD;
		spin_lock(&gl->gl_lockref.lock);
		if (find_last_waiter(gl))
			goto unlock;
		current_gh = find_first_holder(gl);
		if (!may_grant(gl, current_gh, gh))
			goto unlock;
		set_bit(HIF_HOLDER, &gh->gh_iflags);
		list_add_tail(&gh->gh_list, &gl->gl_holders);
		trace_gfs2_promote(gh);
		error = 0;
unlock:
		spin_unlock(&gl->gl_lockref.lock);
		return error;
	}

