/* 학습 해설
 * NILFS2·로그와 Checkpoint
 * 과거 파일시스템 상태를 유지하면서 변경 내용을 새 로그에 쓸 때 현재 상태와 보존된 시점을 구분해야 합니다.
 * NILFS2는 변경을 segment 로그에 기록하고 checkpoint 번호로 상태를 찾습니다. Snapshot으로 보존한 checkpoint와 일반 checkpoint의 수명은 다르며 cleaner가 더 이상 필요 없는 segment를 회수합니다. 현재 inode 파일과 checkpoint의 inode 파일 참조가 연결됩니다.
 * 학습용 이미지에서 checkpoint·snapshot·segment 사용량과 cleaner를 관찰합니다. Snapshot 보존이 공간 회수에 미치는 영향을 확인하고 checkpoint가 무조건 영구 백업이라고 가정하지 않습니다.
 */
int nilfs_attach_checkpoint(struct super_block *sb, __u64 cno, int curr_mnt,
			    struct nilfs_root **rootp)
{
	struct the_nilfs *nilfs = sb->s_fs_info;
	struct nilfs_root *root;
	int err = -ENOMEM;

	root = nilfs_find_or_create_root(
		nilfs, curr_mnt ? NILFS_CPTREE_CURRENT_CNO : cno);
	if (!root)
		return err;

	if (root->ifile)
		goto reuse; /* already attached checkpoint */

	down_read(&nilfs->ns_segctor_sem);
	err = nilfs_ifile_read(sb, root, cno, nilfs->ns_inode_size);
	up_read(&nilfs->ns_segctor_sem);
	if (unlikely(err))
		goto failed;

 reuse:
	*rootp = root;
	return 0;

 failed:

