/* 학습 해설
 * FAT·Cluster Chain
 * 파일 data가 흩어진 cluster에 저장될 때 다음 조각을 찾는 연결표가 필요합니다.
 * FAT entry는 다음 cluster 또는 EOF·free·bad 등의 상태를 나타냅니다. 파일 시작 cluster에서 표를 따라가며 논리 위치를 찾습니다. FAT12·16·32는 entry bit 폭과 접근 방식이 달라 operations로 분리되고 buffer_head가 표 sector 읽기를 관리합니다.
 * 테스트 FAT 이미지에서 시작 cluster와 chain을 읽고 EOF·잘못된 index·루프·파일 크기 검사를 비교합니다. 기존 데이터가 있는 디스크를 수정하는 실습 대신 복제 이미지를 사용합니다.
 */
int fat_ent_read(struct inode *inode, struct fat_entry *fatent, int entry)
{
	struct super_block *sb = inode->i_sb;
	struct msdos_sb_info *sbi = MSDOS_SB(inode->i_sb);
	const struct fatent_operations *ops = sbi->fatent_ops;
	int err, offset;
	sector_t blocknr;

	if (!fat_valid_entry(sbi, entry)) {
		fatent_brelse(fatent);
		fat_fs_error(sb, "invalid access to FAT (entry 0x%08x)", entry);
		return -EIO;
	}

	fatent_set_entry(fatent, entry);
	ops->ent_blocknr(sb, entry, &offset, &blocknr);

	if (!fat_ent_update_ptr(sb, fatent, offset, blocknr)) {
		fatent_brelse(fatent);
		err = ops->ent_bread(sb, fatent, offset, blocknr);
		if (err)
			return err;
	}
	return ops->ent_get(fatent);
}

