/* 학습 해설
 * Pstore·장애 기록의 지속 저장
 * Crash 직전 로그를 재부팅 후 읽으려면 일반 page cache 밖에 기록을 남기는 backend가 필요합니다.
 * Pstore는 persistent backend에 제한된 record를 저장하고 filesystem으로 노출합니다. Ramoops 같은 backend는 보존 메모리 구역을 사용할 수 있습니다. Panic·NMI 등의 경로에서는 block·allocation·lock 사용 조건이 엄격하며 모든 crash 기록을 항상 남긴다고 보장하지 않습니다.
 * 지원 backend와 예약 영역 설정을 확인하고 /sys/fs/pstore의 record를 조회합니다. Log 용량·overwrite·compression·재부팅 시 보존 조건을 확인하고 일반 종료 테스트를 모든 장애 상황의 검증으로 세지 않습니다.
 */
static void pstore_dump(struct kmsg_dumper *dumper,
			struct kmsg_dump_detail *detail)
{
	struct kmsg_dump_iter iter;
	unsigned long	total = 0;
	const char	*why;
	unsigned int	part = 1;
	unsigned long	flags = 0;
	int		saved_ret = 0;
	int		ret;

	why = kmsg_dump_reason_str(detail->reason);

	if (pstore_cannot_block_path(detail->reason)) {
		if (!raw_spin_trylock_irqsave(&psinfo->buf_lock, flags)) {
			pr_err("dump skipped in %s path because of concurrent dump\n",
					in_nmi() ? "NMI" : why);
			return;
		}
	} else {
		raw_spin_lock_irqsave(&psinfo->buf_lock, flags);
	}

	kmsg_dump_rewind(&iter);

	oopscount++;

