 * Configfs·사용자 생성 Kernel Object
 * 사용자가 mkdir·rmdir로 커널 객체를 구성하려면 이름 공간 조작과 객체 생성·수명을 연결해야 합니다.
 * Configfs는 config_item·config_group·subsystem으로 구성 객체를 표현합니다. 사용자 mkdir가 해당 subsystem의 make_item/make_group 동작에 연결되고 attribute로 설정합니다. Kernel이 이미 만든 객체를 주로 보여주는 sysfs와 객체 생성 주체·수명 규약이 다릅니다.
 * 해당 subsystem의 지원 문서에 따라 configfs mount와 group 생성·attribute 설정·제거 순서를 사용합니다. Dependency·symlink·참조가 남은 객체의 제거 제한과 callback 오류를 처리합니다.
 */
int configfs_register_subsystem(struct configfs_subsystem *subsys)
{
	int err;
	struct config_group *group = &subsys->su_group;
	struct dentry *dentry;
	struct dentry *root;
	struct configfs_dirent *sd;
	struct configfs_fragment *frag;

	frag = new_fragment();
	if (!frag)
		return -ENOMEM;

	root = configfs_pin_fs();
	if (IS_ERR(root)) {
		put_fragment(frag);
		return PTR_ERR(root);
	}

	if (!group->cg_item.ci_name)
		group->cg_item.ci_name = group->cg_item.ci_namebuf;

	sd = root->d_fsdata;
	mutex_lock(&configfs_subsystem_mutex);
	link_group(to_config_group(sd->s_element), group);
	mutex_unlock(&configfs_subsystem_mutex);

