/* 학습 해설
 * FSCache·원격 파일의 로컬 캐시
 * 원격 데이터를 반복 읽을 때 로컬 저장소에 cache하되 원격 원본과 일관성을 유지해야 합니다.
 * FSCache는 cache·volume·cookie와 상태·참조 수명으로 netfs의 cache backend 사용을 조정합니다. Netfs는 유효성 판단과 IO 경로를 연결하고 backend는 로컬 cache 저장을 담당합니다. Cache data는 원본을 대체하는 영구 authoritative 복사본으로 보장되지 않습니다.
 * 지원 netfs와 CacheFiles backend 설정에서 hit·miss·coherency·cache 중단을 관찰합니다. Cookie 획득·활성·사용 종료·무효화 규약을 지키고 cache 사용 불가 시 원격 경로의 fallback을 확인합니다.
 */
struct fscache_cache *fscache_acquire_cache(const char *name)
{
	struct fscache_cache *cache;

	ASSERT(name);
	cache = fscache_lookup_cache(name, true);
	if (IS_ERR(cache))
		return cache;

	if (!fscache_set_cache_state_maybe(cache,
					   FSCACHE_CACHE_IS_NOT_PRESENT,
					   FSCACHE_CACHE_IS_PREPARING)) {
		pr_warn("Cache tag %s in use\n", name);
		fscache_put_cache(cache, fscache_cache_put_cache);
		return ERR_PTR(-EBUSY);
	}

	return cache;
}
EXPORT_SYMBOL(fscache_acquire_cache);

