/* 학습 해설
 * NVMEM·비휘발성 Cell 읽기
 * EEPROM·OTP 등에 있는 보정값을 driver마다 raw offset으로 중복 해석하지 않도록 이름 있는 cell API가 필요합니다.
 * NVMEM provider는 저장 영역과 read/write 접근을 제공하고 cell은 offset·길이·bitfield·layout 정보를 연결합니다. Consumer는 cell을 획득하고 읽은 buffer와 길이·post-processing 결과를 사용합니다. Raw bytes와 실제 cell 값의 해석을 구분합니다.
 * 지원 cell 이름과 format·endianness를 확인하고 nvmem_cell_read의 IS_ERR 결과를 먼저 검사합니다. 성공 buffer는 호출자가 kfree하고 cell 참조도 정해진 API로 반환합니다. OTP 등 실제 write 가능성을 읽기 지원과 동일시하지 않습니다.
 */
void *nvmem_cell_read(struct nvmem_cell *cell, size_t *len)
{
	struct nvmem_cell_entry *entry = cell->entry;
	struct nvmem_device *nvmem = entry->nvmem;
	u8 *buf;
	int rc;

	if (!nvmem)
		return ERR_PTR(-EINVAL);

	buf = kzalloc(max_t(size_t, entry->raw_len, entry->bytes), GFP_KERNEL);
	if (!buf)
		return ERR_PTR(-ENOMEM);

	rc = __nvmem_cell_read(nvmem, cell->entry, buf, len, cell->id, cell->index);
	if (rc) {
		kfree(buf);
		return ERR_PTR(rc);
	}

	return buf;
}
EXPORT_SYMBOL_GPL(nvmem_cell_read);

static void *nvmem_cell_prepare_write_buffer(struct nvmem_cell_entry *cell,
					     u8 *_buf, int len)

