/* 학습 해설
 * Hwmon·환경 Sensor 인터페이스
 * 다양한 sensor가 온도·전압·fan 수치를 제공해도 사용자 도구가 일정한 속성 이름과 단위를 읽을 수 있어야 합니다.
 * Hwmon은 chip info·channel config·ops로 sensor 속성과 접근 권한을 등록합니다. is_visible이 지원·권한을 정하고 read/write가 device 값을 연결합니다. Raw register 값은 scale·offset 등 변환을 거쳐 표준 attribute 단위가 될 수 있습니다.
 * 학습용 /sys/class/hwmon 아래 name·temp·in·fan 속성을 조회하고 hwmon sysfs 단위를 확인합니다. Channel 번호·input·limit·alarm·update_interval 의미를 구분하며 임의 limit write를 단순 조회로 취급하지 않습니다.
 */
hwmon_device_register_with_info(struct device *dev, const char *name,
				void *drvdata,
				const struct hwmon_chip_info *chip,
				const struct attribute_group **extra_groups)
{
	if (!dev || !name || !chip)
		return ERR_PTR(-EINVAL);

	if (!chip->ops || !chip->ops->is_visible || !chip->info)
		return ERR_PTR(-EINVAL);

	return __hwmon_device_register(dev, name, drvdata, chip, extra_groups);
}
EXPORT_SYMBOL_GPL(hwmon_device_register_with_info);

/**
 * hwmon_device_register_for_thermal - register hwmon device for thermal subsystem
 * @dev: the parent device
 * @name: hwmon name attribute
 * @drvdata: driver data to attach to created device
 *
 * The use of this function is restricted. It is provided for legacy reasons
 * and must only be called from the thermal subsystem.
 *
 * hwmon_device_unregister() must be called when the device is no
 * longer needed.
 *
 * Returns the pointer to the new device.
