/* 학습 해설
 * TEE·신뢰 실행환경 Session
 * 일반 OS에서 별도 신뢰 환경으로 요청을 보낼 때 user buffer 검증과 session·shared memory 경계를 명확히 해야 합니다.
 * TEE framework는 context·session·shared memory·typed parameter를 implementation operations에 연결합니다. Open session은 UUID·login 정보와 parameter를 검증해 trusted application을 연결합니다. TEE가 있다는 사실만으로 일반 world의 모든 입력이 신뢰되는 것은 아닙니다.
 * 지원 TEE client library와 implementation의 open·invoke·close 규약을 사용합니다. Parameter type·길이·shared memory 소유권·result/origin·취소를 처리하고 kernel ioctl 오류와 trusted application 결과를 구분합니다.
 */
static int tee_ioctl_open_session(struct tee_context *ctx,
				  struct tee_ioctl_buf_data __user *ubuf)
{
	int rc;
	size_t n;
	struct tee_ioctl_buf_data buf;
	struct tee_ioctl_open_session_arg __user *uarg;
	struct tee_ioctl_open_session_arg arg;
	struct tee_ioctl_param __user *uparams = NULL;
	struct tee_param *params = NULL;
	bool have_session = false;

	if (!ctx->teedev->desc->ops->open_session)
		return -EINVAL;

	if (copy_from_user(&buf, ubuf, sizeof(buf)))
		return -EFAULT;

	if (buf.buf_len > TEE_MAX_ARG_SIZE ||
	    buf.buf_len < sizeof(struct tee_ioctl_open_session_arg))
		return -EINVAL;

	uarg = u64_to_user_ptr(buf.buf_ptr);
	if (copy_from_user(&arg, uarg, sizeof(arg)))
		return -EFAULT;

