/* 학습 해설
 * UIO·사용자 공간 장치 Driver
 * 단순 장치의 일부 처리를 사용자 프로세스에서 하려면 MMIO mapping과 interrupt 통지에 최소 kernel 경계가 필요합니다.
 * UIO는 kernel 등록 정보로 device memory mapping과 event counter 읽기·poll을 제공합니다. 사용자 앱이 register protocol을 처리할 수 있지만 DMA isolation·장치 reset·모든 interrupt 처리를 자동으로 제공하는 VFIO와 같은 계약은 아닙니다. Event counter는 payload data가 아닙니다.
 * 격리된 지원 장치의 /dev/uioN과 sysfs map size·offset을 확인합니다. Register width·barrier·interrupt re-enable·hot-unplug·권한을 처리하고 임의 물리 주소를 mmap하지 않습니다.
 */
static ssize_t uio_read(struct file *filep, char __user *buf,
			size_t count, loff_t *ppos)
{
	struct uio_listener *listener = filep->private_data;
	struct uio_device *idev = listener->dev;
	DECLARE_WAITQUEUE(wait, current);
	ssize_t retval = 0;
	s32 event_count;

	if (count != sizeof(s32))
		return -EINVAL;

	add_wait_queue(&idev->wait, &wait);

	do {
		mutex_lock(&idev->info_lock);
		if (!idev->info || !idev->info->irq) {
			retval = -EIO;
			mutex_unlock(&idev->info_lock);
			break;
		}
		mutex_unlock(&idev->info_lock);

		set_current_state(TASK_INTERRUPTIBLE);

		event_count = atomic_read(&idev->event);

