/* 학습 해설
 * VDPA·Virtio Data Path 가속
 * Virtio 규약으로 guest를 연결하면서 data path를 hardware 등에 맡기려면 queue·feature·상태 설정 인터페이스가 필요합니다.
 * vDPA device는 virtqueue address·size·ready·notification·feature·config·status operations를 제공합니다. Control 계약은 virtio와 연결되지만 가속된 data path의 구현·DMA mapping·migration 지원은 device마다 다릅니다. Queue 준비 전 data를 처리하게 하면 안 됩니다.
 * 지원 vDPA 관리 도구와 vhost-vdpa/virtio-vdpa 연결을 사용합니다. Feature 협상·queue 배치·DMA/IOMMU·status reset·migration 조건을 확인하고 모든 vDPA 장치가 같은 offload와 migration을 지원한다고 가정하지 않습니다.
 */
void vdpa_set_status(struct vdpa_device *vdev, u8 status)
{
	down_write(&vdev->cf_lock);
	vdev->config->set_status(vdev, status);
	up_write(&vdev->cf_lock);
}
EXPORT_SYMBOL(vdpa_set_status);

static struct genl_family vdpa_nl_family;

static int vdpa_dev_probe(struct device *d)
{
	struct vdpa_device *vdev = dev_to_vdpa(d);
	struct vdpa_driver *drv = drv_to_vdpa(vdev->dev.driver);
	const struct vdpa_config_ops *ops = vdev->config;
	u32 max_num, min_num = 1;
	int ret = 0;

	d->dma_mask = &d->coherent_dma_mask;
	ret = dma_set_mask_and_coherent(d, DMA_BIT_MASK(64));
	if (ret)
		return ret;

	max_num = ops->get_vq_num_max(vdev);
	if (ops->get_vq_num_min)
		min_num = ops->get_vq_num_min(vdev);

